const item = $input.first().json;

const fromRaw = item.from?.text || item.from || item.headers?.from || '';
const fromEmail = fromRaw.match(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/i)?.[0] || fromRaw;
const subject = item.subject || item.headers?.subject || '(No subject)';
const plain = item.textPlain || item.text || item.body || '';
const html = item.textHtml || item.html || '';
const body = String(plain || html).replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();

const originalMessageId = item.messageId || item.headers?.['message-id'] || item.headers?.messageId || '';
const replySubject = /^re:/i.test(subject) ? subject : `Re: ${subject}`;

return [{
  json: {
    fromRaw,
    fromEmail,
    subject,
    replySubject,
    originalMessageId,
    body,
    openaiPayload: {
      model: 'gpt-5-mini',
      instructions: [
        'You write professional customer email replies for the business mailbox.',
        'Be warm, concise, helpful, and polished.',
        'Do not invent facts, prices, availability, policies, order details, or commitments that are not present in the email.',
        'If required information is missing, ask one clear follow-up question.',
        'Do not include a subject line, markdown, signatures, or placeholders.',
        'Write only the body of the email reply.'
      ].join(' '),
      input: `Incoming email from: ${fromRaw}\nSubject: ${subject}\n\nMessage:\n${body}`,
      max_output_tokens: 700,
      store: false
    }
  }
}];

const openai = $input.first().json;
const previous = $('Prepare Email For OpenAI').first().json;

const outputText = openai.output_text
  || openai.output?.flatMap((entry) => entry.content || []).find((content) => content.type === 'output_text')?.text
  || openai.choices?.[0]?.message?.content
  || '';

const cleanedReply = String(outputText).trim();
if (!cleanedReply) {
  throw new Error('OpenAI returned an empty email reply.');
}

return [{
  json: {
    to: previous.fromEmail,
    replySubject: previous.replySubject,
    replyBody: cleanedReply,
    originalMessageId: previous.originalMessageId
  }
}];
